"""Author the shared command catalogue and its full Russian phrase reference."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
entries=[]
def add(id,title,category,description,action,phrases,**extra):
    phrases=list(dict.fromkeys(phrases))
    entries.append(dict(id=id,title=title,category=category,description=description,action=list(action),prompt=phrases[0],phrases=phrases,**extra))

def opening(id,title,category,description,kind,arg,names,genitive=None,dative=None):
    names=names.split('|')
    phrases=[f'{verb} {name}' for name in names for verb in ['Открой','Открыть','Запусти','Запустить','Покажи','Показать']]
    if genitive:phrases.extend([f'Запуск {genitive}',f'Открытие {genitive}'])
    if dative:phrases.extend([f'Перейди к {dative}',f'Переключись на {names[0]}'])
    add(id,title,category,description,(kind,arg),phrases,targets=names)

